css:
.kx { font-family: Inter, -apple-system, sans-serif; font-size: 12px; color: #1f2328; }
.kx table { width: 100%; border-collapse: collapse; }
.kx .head td { vertical-align: top; }
.kx .logo { max-height: 64px; max-width: 160px; }
.kx .client-logo { max-height: 40px; max-width: 120px; float: right; }
.kx .title { font-size: 20px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; text-align: right; }
.kx .muted { color: #6b7280; }
.kx .small { font-size: 11px; }
.kx .box { border: 1px solid #e5e7eb; border-radius: 8px; padding: 10px 12px; }
.kx .lines th { background: #f3f4f6; text-align: left; font-weight: 600; padding: 7px 8px; border-bottom: 1px solid #e5e7eb; }
.kx .lines th.num { text-align: right; }
.kx .lines td { padding: 7px 8px; border-bottom: 1px solid #f0f0f0; vertical-align: top; }
.kx .num { text-align: right; white-space: nowrap; }
.kx .totals td { padding: 4px 8px; }
.kx .grand td { border-top: 1px solid #1f2328; font-weight: 700; font-size: 14px; padding-top: 8px; }
.kx .gap { height: 14px; }
.kx .pre { white-space: pre-line; }
.kx .qr img { width: 110px; height: 110px; }

html:
{%- set p = bill_print(doc) -%}
{%- macro money(v) -%}{{ frappe.format_value(v, {"fieldtype": "Currency", "options": "currency"}, doc) }}{%- endmacro -%}
<div class="kx">
<table class="head">
	<tr>
		<td style="width: 55%">
			{% if p.firm.logo %}<img class="logo" src="{{ p.firm.logo }}"><br>{% endif %}
			<div style="font-size: 15px; font-weight: 700; margin-top: 6px">{{ p.firm.name or doc.company }}</div>
			{% if p.firm.address %}<div class="pre muted small">{{ p.firm.address }}</div>{% endif %}
			{% if p.firm.gstin %}<div class="small">GSTIN: <b>{{ p.firm.gstin }}</b></div>{% endif %}
			{% if p.firm.state %}<div class="small muted">State: {{ p.firm.state }}</div>{% endif %}
		</td>
		<td style="width: 45%">
			<div class="title">{{ _(p.title) }}</div>
			<table class="small" style="margin-top: 8px">
				<tr><td class="muted">{{ _("Number") }}</td><td class="num"><b>{{ doc.name }}</b></td></tr>
				<tr><td class="muted">{{ _("Date") }}</td><td class="num">{{ frappe.format_value(doc.posting_date, {"fieldtype": "Date"}) }}</td></tr>
				<tr><td class="muted">{{ _("Due") }}</td><td class="num">{{ frappe.format_value(doc.due_date, {"fieldtype": "Date"}) }}</td></tr>
				{% if doc.docstatus == 0 %}<tr><td colspan="2" class="num muted">{{ _("Draft, not yet issued") }}</td></tr>{% endif %}
				{% if doc.docstatus == 2 %}<tr><td colspan="2" class="num" style="color: #b91c1c">{{ _("Cancelled") }}</td></tr>{% endif %}
			</table>
		</td>
	</tr>
</table>
<div class="gap"></div>
<div class="box">
	{% if p.client.logo %}<img class="client-logo" src="{{ p.client.logo }}">{% endif %}
	<div class="muted small">{{ _("Billed to") }}</div>
	<div style="font-weight: 700; font-size: 13px">{{ p.client.client_name or doc.customer_name }}</div>
	{% if p.client.billing_address %}<div class="pre small">{{ p.client.billing_address }}</div>{% endif %}
	{% if p.client.gstin %}<div class="small">GSTIN: <b>{{ p.client.gstin }}</b></div>{% endif %}
	{% if p.place_of_supply %}<div class="small muted">{{ _("Place of supply") }}: {{ p.place_of_supply }}</div>{% endif %}
</div>
<div class="gap"></div>
<table class="lines">
	<tr>
		<th style="width: 5%">#</th>
		<th>{{ _("Description") }}</th>
		<th style="width: 11%">SAC</th>
		<th class="num" style="width: 10%">{{ _("Qty") }}</th>
		<th class="num" style="width: 14%">{{ _("Rate") }}</th>
		<th class="num" style="width: 15%">{{ _("Amount") }}</th>
	</tr>
	{% for row in doc.items %}
	<tr>
		<td>{{ row.idx }}</td>
		<td>{{ row.description | striptags }}</td>
		<td>{{ row.sac_code or "" }}</td>
		<td class="num">{{ frappe.format_value(row.qty, {"fieldtype": "Float"}) }}{% if row.uom == "Hour" %} {{ _("h") }}{% endif %}</td>
		<td class="num">{{ money(row.rate) }}</td>
		<td class="num">{{ money(row.amount) }}</td>
	</tr>
	{% endfor %}
</table>
<table class="totals" style="width: 50%; margin-left: 50%; margin-top: 8px">
	<tr><td class="muted">{{ _("Subtotal") }}</td><td class="num">{{ money(doc.net_total) }}</td></tr>
	{% for tax in doc.taxes %}{% if tax.tax_amount %}
	<tr><td class="muted">{{ tax.description | replace("Output ", "") }} @ {{ "%g" % tax.rate }}%</td><td class="num">{{ money(tax.tax_amount) }}</td></tr>
	{% endif %}{% endfor %}
	{% if doc.rounding_adjustment %}<tr><td class="muted">{{ _("Rounding") }}</td><td class="num">{{ money(doc.rounding_adjustment) }}</td></tr>{% endif %}
	<tr class="grand"><td>{{ _("Total") }}</td><td class="num">{{ money(doc.rounded_total or doc.grand_total) }}</td></tr>
	{% if doc.docstatus == 1 and doc.outstanding_amount != (doc.rounded_total or doc.grand_total) %}
	<tr><td class="muted">{{ _("Still due") }}</td><td class="num">{{ money(doc.outstanding_amount) }}</td></tr>
	{% endif %}
</table>
<div class="small" style="margin-top: 6px"><span class="muted">{{ _("In words") }}:</span> {{ p.in_words }}</div>
{% if p.composition_note %}<div class="small" style="margin-top: 6px"><b>{{ p.composition_note }}</b></div>{% endif %}
<div class="gap"></div>
{% if p.firm.bank_details or p.qr %}
<table class="box">
	<tr>
		<td style="vertical-align: top">
			<div class="muted small">{{ _("To pay") }}</div>
			{% if p.firm.bank_details %}<div class="pre small">{{ p.firm.bank_details }}</div>{% endif %}
			{% if p.firm.upi_id %}<div class="small">UPI: <b>{{ p.firm.upi_id }}</b></div>{% endif %}
		</td>
		{% if p.qr %}
		<td class="qr" style="width: 130px; text-align: center">
			<img src="{{ p.qr }}"><div class="small muted">{{ _("Scan to pay") }} {{ money(p.due) }}</div>
		</td>
		{% endif %}
	</tr>
</table>
{% endif %}
<div class="small muted" style="margin-top: 14px; text-align: center">{{ _("This is a computer-generated document and needs no signature.") }}</div>
</div>
